-- current regulatory_market_access_primary_sources row.
update public.regulatory_market_access_evidence set tier='medical_limited_trade',authority_name='Swissmedic',authority_url='https://www.swissmedic.ch/swissmedic/en/home/humanarzneimittel/besondere-arzneimittelgruppen--ham-/authorised-narcotics/cannabis-agency.html',rationale='Current Swissmedic Cannabis Agency material identifies cannabis for medical purposes within the authorised-narcotics framework and provides licensing, import/export and domestic-trade controls.',source_snapshot_sha256='ec35526b04e58789e479efefce4bafc520eeb45b66a166a123c480b8b7cf3312',verified_at=now(),expires_at=now()+interval '30 days',active=true where evidence_key='hv-mkt-ch-20260907';
