insert into public.regulatory_market_access_primary_sources (jurisdiction_iso2,jurisdiction_level,parent_iso2,source_class,authority_name,authority_url,source_title,source_effective_date,source_snapshot_sha256,verified_at,expires_at,notes) values ('US-IL','subnational','US','primary_regulator','Illinois Department of Financial and Professional Regulation','https://idfpr.illinois.gov/profs/adultusecan.html','Adult Use Cannabis Program','2026-09-23','738b555e965f0d8b5a8607279e0a5b330158b9e56e4a10dd53b548be58e328d5',now(),now()+interval '30 days','Current first-party adult-use cannabis licensing/regulation authority.') on conflict (jurisdiction_iso2) do update set authority_name=excluded.authority_name,authority_url=excluded.authority_url,source_title=excluded.source_title,source_effective_date=excluded.source_effective_date,source_snapshot_sha256=excluded.source_snapshot_sha256,verified_at=excluded.verified_at,expires_at=excluded.expires_at,notes=excluded.notes;
